    canonicalEvidence: "{\"id\":\"dcceew-refrigerant-recovery-licensing\",\"title\":\"Refrigerant handling and end-of-life recovery\",\"publisher\":\"Department of Climate Change, Energy, the Environment and Water\",\"url\":\"https://www.dcceew.gov.au/environment/protection/ozone/rac/technicians\",\"topic\":\"safety_consumer_rights\",\"audience\":[\"household\",\"renter\",\"strata\",\"trade\",\"assessor\"],\"jurisdiction\":\"Australia under national ozone and synthetic greenhouse gas law\",\"effectiveFrom\":null,\"effectiveTo\":null,\"reviewedAt\":\"2026-10-13\",\"reviewDue\":\"2026-11-13\",\"reuseBasis\":\"Commonwealth material, factual summary with attribution\",\"volatilityClass\":\"volatile_program\",\"storagePolicy\":\"local_factual_summary\",\"official\":true,\"summary\":\"A Refrigerant Handling Licence is required for work with regulated refrigerant that could cause leakage, including installation, service, maintenance and decommissioning. It is illegal to release regulated refrigerant to air. End-of-life air conditioners, heat pumps and refrigeration equipment must have refrigerant recovered by appropriately licensed personnel before dismantling, recycling or disposal.\",\"keywords\":[\"refrigerant handling licence\",\"vent refrigerant\",\"release refrigerant\",\"recover refrigerant\",\"decommission air conditioner\",\"split system disposal\",\"heat pump disposal\",\"ARC licence\",\"illegal release\"]}",
