    canonicalEvidence: "{\"id\":\"esv-carbon-monoxide-alarm-signals\",\"title\":\"Carbon monoxide alarms for domestic use\",\"publisher\":\"Energy Safe Victoria\",\"url\":\"https://www.energysafe.vic.gov.au/industry-guidance/gas/gas-information-sheets/gis-36-carbon-monoxide-alarms-domestic-use\",\"topic\":\"safety_consumer_rights\",\"audience\":[\"household\",\"renter\",\"strata\",\"trade\",\"assessor\"],\"jurisdiction\":\"Victoria, with gas emergency and servicing pathways varying by jurisdiction\",\"effectiveFrom\":null,\"effectiveTo\":null,\"reviewedAt\":\"2026-10-13\",\"reviewDue\":\"2026-11-13\",\"reuseBasis\":\"Official public material, locally maintained factual summary; confirm the current instrument before regulated work\",\"volatilityClass\":\"volatile_program\",\"storagePolicy\":\"local_factual_summary\",\"official\":true,\"summary\":\"A CO alarm is a backup precaution, not a substitute for correct gas-appliance installation, ventilation and servicing. CO detection, alarm fault and sensor end-of-life signals should be distinguishable, and the exact sound pattern must be checked against the model instructions. A continuing CO alarm or symptoms require a safety response, while a periodic chirp may indicate battery, fault or end-of-life and still needs prompt manual-based action.\",\"keywords\":[\"carbon monoxide alarm\",\"continuous alarm\",\"periodic chirp\",\"alarm fault\",\"sensor end of life\",\"battery warning\",\"manufacturer instructions\",\"gas heater\",\"ventilation\"]}",
