    canonicalEvidence: "{\"id\":\"energy-gov-electrification\",\"title\":\"Hot water systems\",\"publisher\":\"energy.gov.au, Australian Government\",\"url\":\"https://www.energy.gov.au/households/hot-water-systems\",\"topic\":\"heat_pump_hot_water\",\"audience\":[\"household\",\"renter\",\"strata\",\"trade\"],\"jurisdiction\":\"Australia\",\"effectiveFrom\":null,\"effectiveTo\":null,\"reviewedAt\":\"2026-10-13\",\"reviewDue\":\"2026-11-13\",\"reuseBasis\":\"Commonwealth material, factual summary with attribution\",\"volatilityClass\":\"volatile_program\",\"storagePolicy\":\"local_factual_summary\",\"official\":true,\"summary\":\"Heat-pump water heaters transfer heat from surrounding air, so efficiency and recovery can change with ambient temperature. Size for occupants, draw profile, usable tank volume and peak recovery in the local climate; also check noise, airflow, condensate, electrical supply, timer or tariff controls, warranty and local service. Electrical, plumbing and refrigerant work must use the licences required in the jurisdiction. Incentive eligibility depends on the exact CER-listed model and installation conditions.\",\"keywords\":[\"heat pump hot water\",\"heat pump water heater\",\"hpwh\",\"hot water\",\"tank size\",\"noise\",\"tariff\",\"electrification\",\"gas replacement\",\"hot water demand\",\"cold climate recovery\",\"condensate drain\",\"timer control\",\"warranty service\",\"cer exact model\",\"licensed installation\"]}",
